style.css:
@-moz-document domain("pinterest.com") {
/* 1. Main Background */
    body, html, [role="main"], div[data-test-id="main-container"] {
        background-color: #F0E6FF !important; /* Soft Lavender Background */
    }

    /* 2. Navigation Bar & Search Bar */
    div[data-test-id="header"] {
        background-color: #E6D5FF !important; /* Slightly darker lavender for header */
        border-bottom: 1px solid #D1B3FF !important;
    }
    
    div[data-test-id="search-box"] input {
        background-color: #FFFFFF !important;
        border: 2px solid #C499FF !important; /* Purple accent border */
    }

    /* 3. Text and Icons Color */
    h1, h2, h3, p, span, div, svg {
        color: #4A3E56 !important; /* Deep plum text for readability */
    }

    /* 4. Buttons and Interactive Elements */
    /* Target primary action buttons (like Save) */
    div[data-test-id="VisualPinsGrid"] [role="button"], 
    div[role="listitem"] button,
    [data-test-id="board-card"],
    .red-button-class-placeholder {
        background-color: #B388FF !important; /* Vibrant lavender/purple accent */
        color: #FFFFFF !important;
    }
    
    div[data-test-id="VisualPinsGrid"] [role="button"]:hover {
        background-color: #9E66FF !important; /* Darker purple on hover */
    }

    /* 5. Navigation Icons Active State Background */
    div[data-test-id="header"] [role="link"] div:hover,
    div[data-test-id="header"] [role="button"] div:hover {
        background-color: #D1B3FF !important;
    }
}
